package app.daysemble

import android.view.View
import android.view.animation.PathInterpolator
import androidx.core.splashscreen.SplashScreenViewProvider

/**
 * Hand-off from the system launch splash to the app.
 *
 * The splash and the app are separate stages: the splash shows the complete logo tile
 * (drawable/splash_icon, generated by scripts/import_logos.py to fit Android's circular splash
 * mask), and the app's first frame (Today, or the welcome screen on first use) is already drawn
 * underneath when this runs. So the exit is a short, quiet fade of the splash with the logo
 * settling very slightly; there is no reveal shape, no extra waiting and nothing to line up.
 * (It replaces a closing circular reveal that left a disc of splash background over the middle of
 * the app and then vanished in one frame.)
 *
 * With reduced motion the splash is removed at once.
 */
internal object SplashExit {
    private const val DURATION = 220L
    private val accelerate = PathInterpolator(0.3f, 0f, 0.8f, 0.15f)

    fun play(provider: SplashScreenViewProvider, reduced: Boolean) {
        val splash = provider.view
        if (reduced || !splash.isAttachedToWindow) {
            provider.remove()
            return
        }
        val icon: View? = runCatching { provider.iconView }.getOrNull()
        icon?.animate()?.scaleX(0.96f)?.scaleY(0.96f)?.setInterpolator(accelerate)?.setDuration(DURATION)?.start()
        splash.animate()
            .alpha(0f)
            .setInterpolator(accelerate)
            .setDuration(DURATION)
            .withEndAction { provider.remove() }
            .start()
    }
}
